package com.wx.community.controller;
import com.wx.community.domain.*; import com.wx.community.service.CommunityService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController { private final CommunityService s; public AdminController(CommunityService s){this.s=s;} @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("users",0,"activities",s.activities().size(),"orders",0,"points",0);} @GetMapping("/{resource}") public List<?> resource(@PathVariable String resource){ if("activities".equals(resource)) return s.activities(); if("products".equals(resource)) return s.products(); return List.of(); } @GetMapping("/users/{id}") public User user(@PathVariable Long id){return s.user(id);} @PostMapping("/users/{id}/points") public User points(@PathVariable Long id,@RequestParam int delta,@RequestParam(defaultValue="ADMIN_ADJUST")String type,@RequestParam(defaultValue="管理员调整")String remark){return s.adjustPoints(id,delta,type,remark);} @GetMapping("/orders/{uid}") public List<Order> orders(@PathVariable Long uid){return s.orders(uid);} }
